mapper.select:
SELECT object_kind,object_id,state,revision,latest_event_id,ledger_sequence,previous_status,trashed_at,updated_at
FROM privacy_object_state WHERE owner_id=#{owner} AND state=#{state}
AND (object_kind>#{afterKind} OR (object_kind=#{afterKind} AND object_id>#{afterId}))
ORDER BY object_kind,object_id LIMIT #{limit}

mapper.update:
UPDATE privacy_object_state SET state=#{state},revision=revision+1,latest_event_id=#{eventId},
  ledger_sequence=#{sequence},previous_status=#{previousStatus},trashed_at=#{trashedAt},updated_at=#{now}
WHERE owner_id=#{owner} AND object_kind=#{kind} AND object_id=#{id}
  AND revision=#{expectedRevision} AND revision<9007199254740991
